from rdkit import Chem
from rdkit.Geometry import Point3D
import numpy as np
m=Chem.RWMol(); ids={}; xy={}
def atom(name, sym, x,y, charge=0, noimp=False):
 a=Chem.Atom(sym); a.SetFormalCharge(charge);a.SetNoImplicit(noimp)
 idx=m.AddAtom(a);ids[name]=idx;xy[name]=(x,y);return idx
def b(i,j,ty='s'):
 ty={'s':Chem.BondType.SINGLE,'d':Chem.BondType.DOUBLE,'a':Chem.BondType.AROMATIC}[ty]
 m.AddBond(ids[i],ids[j],ty)
# first dibenzodiaza scaffold
for name,x,y in [('L1',74,56),('L2',108,53),('L3',124,71),('L4',106,95),('L5',71,102),('L6',57,82),('R1',157,71),('R2',185,53),('R3',216,58),('R4',217,82),('R5',189,101),('R6',160,96)]:atom(name,'C',x,y)
for ring in [('L1','L2','L3','L4','L5','L6'),('R1','R2','R3','R4','R5','R6')]:
 for i in range(6):b(ring[i],ring[(i+1)%6],'a')
b('L3','R1')
atom('NA','N',126,113,charge=-1,noimp=True);b('NA','L4');b('NA','R6')
for side,core,xx,yy in [('L','L1',59,40),('R','R3',244,39)]:
 atom(side+'T','C',xx,yy);b(side+'T',core)
 points=[(27,44),(42,19),(77,14)] if side=='L' else [(244,14),(273,20),(273,43)]
 for i,(x,y) in enumerate(points):atom(f'{side}Me{i}','C',x,y);b(side+'T',f'{side}Me{i}')
# imidazole ylides: carbene donor [c-], one n+ with other n neutral. Aromatic N atoms at two sides
for key, sym, x,y,charge in [('LNtop','N',53,126,0),('LCa','C',20,135,0),('LCb','C',11,161,0),('LNbottom','N',39,169,1),('LCdon','C',64,149,-1),('RNtop','N',191,128,0),('RCa','C',217,135,0),('RCb','C',209,161,0),('RNbottom','N',175,169,1),('RCdon','C',165,149,-1)]:
 atom(key,sym,x,y,charge=charge,noimp=(key.endswith('don')))
for ring in [('LNtop','LCa','LCb','LNbottom','LCdon'),('RNtop','RCa','RCb','RNbottom','RCdon')]:
 for i in range(5):b(ring[i],ring[(i+1)%5],'a')
b('L5','LNtop');b('R5','RNtop')
# bottom 2-substituted pyridine (left NHC links via methylene, right NHC links via alkylated carbon)
atom('CH2','C',51,211);b('LNbottom','CH2')
for nm,s,x,y in [('PN','N',99,187),('PC2','C',117,193),('PC3','C',111,216),('PC4','C',85,239),('PC5','C',68,235),('PC6','C',74,212)]:atom(nm,s,x,y)
pyr=('PN','PC2','PC3','PC4','PC5','PC6')
for i in range(6):b(pyr[i],pyr[(i+1)%6],'a')
b('PC6','CH2')
atom('Cbridge','C',144,175,noimp=True);b('PC2','Cbridge');b('Cbridge','RNbottom')
# trifluoromethylsulfonate ester, bonded through O to bridge carbon
for nm,s,x,y in [('Oester','O',163,202),('S','S',184,216),('Oa','O',183,239),('Ob','O',207,208),('CF3','C',164,233),('F1','F',145,251),('F2','F',175,258),('F3','F',147,223)]:atom(nm,s,x,y)
b('Cbridge','Oester');b('Oester','S');b('S','Oa','d');b('S','Ob','d');b('S','CF3')
for nm in ('F1','F2','F3'):b('CF3',nm)
mol=m.GetMol()
try: Chem.SanitizeMol(mol);print('sanitized',Chem.MolToSmiles(mol))
except Exception as e:print('sanitization error',e)
# construct 3D guess from drawing; give asymmetric out-of-plane deflection so relaxation reaches 3D conformer
conf=Chem.Conformer(mol.GetNumAtoms());conf.Set3D(True)
z={}
for n in ids:
 if n.startswith('R') and n not in ('R1','R2','R3','R4','R5','R6'):z[n]=0.65
 if n.startswith('P'):z[n]=-0.8
 if n in ('CH2','LNbottom','LCb','LCa'):z[n]=-0.35
 if n in ('Cbridge','Oester','S','Oa','Ob','CF3','F1','F2','F3'):z[n]=1.15
z.update({'Cbridge':1.0,'RNbottom':0.6,'PC2':-0.55,'PC3':-0.9,'PN':-0.65,'Oester':1.75,'S':2.1,'Oa':2.0,'Ob':2.65,'CF3':1.85,'F1':1.8,'F2':2.55,'F3':1.4})
for name,i in ids.items():
 x,y=xy[name];conf.SetAtomPosition(i,Point3D((x-117)*0.052,(149-y)*0.052,z.get(name,0)))
mol.AddConformer(conf)
mol=Chem.AddHs(mol,addCoords=True)
print('heavy',len(ids),'H',mol.GetNumAtoms()-len(ids),'total',mol.GetNumAtoms()+1)
# Insert Fe after hydrogens and explicitly correct attached hydrogen count
with open('initial.xyz','w') as f:
 f.write(str(mol.GetNumAtoms()+1)+'\nTriplet Fe organometallic complex with triflate ester\n')
 for a in mol.GetAtoms():
  pos=mol.GetConformer().GetAtomPosition(a.GetIdx());f.write(f'{a.GetSymbol():2s} {pos.x:.7f} {pos.y:.7f} {pos.z:.7f}\n')
 f.write('Fe 0.0000000 0.0000000 0.0400000\n')
print('Fe index',mol.GetNumAtoms());print('donor indices',[(n,ids[n]) for n in ['NA','LCdon','RCdon','PN','Cbridge']])
